    11→/**
    12→ * @property ArchivoRepository $repositorio
    13→ */
    14→class ArchivoService extends BaseService
    15→{
    16→    use ArchivoTrait;
    17→
    18→    /**
    19→     * Constructor.
    20→     *
    21→     * @param ArchivoRepository $repositorio Repositorio de archivos.
    22→     * @return void
    23→     * @author Daniel Beltrán
    24→     */
    25→    public function __construct(ArchivoRepository $repositorio) {
    26→        parent::__construct($repositorio);
    27→    }
    28→
    29→    /**
    30→     * Guardar varios archivos.
    31→     *
    32→     * @param string $modelo Modelo al que pertenecen los archivos.
    33→     * @param int $id ID del modelo.
    34→     * @param array $archivos Archivos a guardar.
    35→     * @param string $carpeta Carpeta donde se guardarán los archivos (tiene que estar dentro de 'private/archivos/').
    36→     * @param bool $conservar_nombre_original Indica si se conservará el nombre original de los archivos.
    37→     * @param ?bool $incluir_id_en_carpeta Indica si debe generarse un directorio adicional con el ID del modelo.
    38→     * @return void
    39→     * @author Daniel Beltrán
    40→     * @author Andres Gonzalez
    41→     */
    42→    public function guardarVarios(string $modelo, int $id, array $archivos, string $carpeta, bool $conservar_nombre_original = false, ?bool $incluir_id_en_carpeta = true): void {
    43→        $ruta = "private/archivos/{$carpeta}";
    44→
    45→        if ($incluir_id_en_carpeta) {
    46→            $ruta .= "/{$id}";
    47→        }
    48→
    49→        $this->generarDirectorios("app/{$ruta}");
    50→
    51→        foreach ($archivos as $llave => $archivo) {
    52→            $nombre_original = str_replace('_', '-', $llave) . date('YmdHis') . '.' . $archivo->getClientOriginalExtension();
    53→            $nombre_archivo  = $this->generarNombreArchivo($archivo);
    54→            $this->guardarArchivoEnRuta($archivo, $ruta, $nombre_archivo);
    55→
    56→            $this->repositorio->crear([
    57→                'modelo'                  => $modelo,
    58→                'modelo_id'               => $id,
    59→                'nombre'                  => $llave,
    60→                'nombre_original_archivo' => $conservar_nombre_original ? $archivo->getClientOriginalName() : null,
    61→                'ruta'                    => $ruta . '/' . $nombre_archivo
    62→            ]);
    63→        }
    64→    }
    65→
    66→    /**
    67→     * Guardar varios archivos en base64.
    68→     *
    69→     * @param string $modelo Modelo al que pertenecen los archivos.
    70→     * @param int $id ID del modelo.
    71→     * @param array $archivos Archivos a guardar.
    72→     * @param string $carpeta Carpeta donde se guardarán los archivos (tiene que estar dentro de 'private/archivos/').
    73→     * @param bool $conservar_nombre_original Indica si se conservará el nombre original de los archivos.
    74→     * @return void
    75→     * @author Daniel Beltrán
    76→     */
    77→    public function guardarVariosBase64(string $modelo, int $id, array $archivos, string $carpeta, bool $conservar_nombre_original = false): void {
    78→        $this->generarDirectorios("app/private/archivos/{$carpeta}/{$id}");
    79→        $ruta = "private/archivos/{$carpeta}/{$id}";
    80→
    81→        foreach ($archivos as $llave => $valor) {
    82→            if ($conservar_nombre_original) {
    83→                $nombre_archivo = $this->guardarArchivoBase64EnRuta($valor, $ruta, str_replace('_', '-', $llave) . date('YmdHis'));
    84→            } else {
    85→                $nombre_archivo = $this->guardarArchivoBase64EnRuta($valor, $ruta);
    86→            }
    87→
    88→            $this->repositorio->crear([
    89→                'modelo'    => $modelo,
    90→                'modelo_id' => $id,
    91→                'nombre'    => $llave,
    92→                'ruta'      => $ruta . '/' . $nombre_archivo
    93→            ]);
    94→        }
    95→    }
    96→
    97→    /**
    98→     * Abrir un archivo.
    99→     *
   100→     * @param int $id ID del archivo.
   101→     * @return Response
   102→     * @author Daniel Beltrán
   103→     */
   104→    public function abrir(int $id): Response {
   105→        $archivo = $this->repositorio->getUno($id);
   106→        return $this->obtenerArchivoDesdeRuta($archivo->ruta);
   107→    }
   108→
   109→    /**
   110→     * Eliminar un archivo.
   111→     *
   112→     * @param int $id ID del archivo.
   113→     * @return void
   114→     * @author Daniel Beltrán
   115→     */
   116→    public function eliminar(int $id): void {
   117→        $archivo = $this->repositorio->getUno($id);
   118→        $this->eliminarArchivoDesdeRuta($archivo->ruta);
   119→        $this->repositorio->eliminar($id);
   120→    }
   121→
   122→    /**
   123→     * Eliminar todos los archivos de un modelo.
   124→     *
   125→     * @param string $modelo Modelo al que pertenecen los archivos.
   126→     * @param int $id ID del modelo.
   127→     * @param ?string $nombre Nombre del tipo de archivo.
   128→     * @return void
   129→     * @author Daniel Beltrán
   130→     */
   131→    public function eliminarPorModelo(string $modelo, int $id, ?string $nombre = null): void {
   132→        $archivos = $this->repositorio->getTodo(new Request([
   133→            'modelo'    => $modelo,
   134→            'modelo_id' => $id,
   135→            'nombre'    => $nombre
   136→        ]));
   137→
   138→        if (!is_null($archivos)) {
   139→            foreach ($archivos as $archivo) {
   140→                $this->eliminarArchivoDesdeRuta($archivo->ruta);
   141→                $this->repositorio->eliminar($archivo->id);
   142→            }
   143→        }
   144→    }
   145→}
