     3→namespace App\Http\Services\Vacantes;
     4→
     5→use Illuminate\Http\Request;
     6→use App\Http\Services\BaseService;
     7→use Illuminate\Support\Collection;
     8→use App\Models\Vacantes\Vacante;
     9→use App\Models\Vacantes\MovimientoVacante;
    10→use App\Models\Vacantes\EtapaMovimientoVacante;
    11→use App\Models\Vacantes\EtapaMovimientoVacanteConfiguracion;
    12→use App\Http\Repositories\Vacantes\EtapaMovimientoVacanteRepository;
    13→use App\Http\Repositories\Vacantes\EtapaMovimientoVacanteConfiguracionRepository;
    14→use App\Http\Repositories\Procesos\ProcesoRepository;
    15→
    16→/**
    17→ * @property EtapaMovimientoVacanteConfiguracionRepository $repositorio
    18→ */
    19→class EtapaMovimientoVacanteConfiguracionService extends BaseService
    20→{
    21→    /**
    22→     * Constructor.
    23→     *
    24→     * @param EtapaMovimientoVacanteConfiguracionRepository $repositorio Repositorio de configuraciones de movimientos de etapas de vacantes.
    25→     * @param EtapaMovimientoVacanteRepository $etapa_movimiento_vacante_repositorio Repositorio de movimientos de etapas de vacantes.
    26→     * @return void
    27→     * @author Fahibram Cárcamo
    28→     * @author Daniel Beltrán
    29→     */
    30→    public function __construct(
    31→        EtapaMovimientoVacanteConfiguracionRepository $repositorio,
    32→        protected EtapaMovimientoVacanteRepository $etapa_movimiento_vacante_repositorio,
    33→        protected ProcesoRepository $proceso_repositorio
    34→    ) {
    35→        parent::__construct($repositorio);
    36→    }
    37→
    38→    /**
    39→     * Sincronizar la configuración del movimiento de la etapa.
    40→     *
    41→     * @param Request $request Contenido de la petición.
    42→     * @return EtapaMovimientoVacanteConfiguracion
    43→     * @author Daniel Beltrán
    44→     */
    45→    public function sincronizar(Request $request): EtapaMovimientoVacanteConfiguracion {
    46→        // Agregar las condiciones de búsqueda
    47→        $condiciones = [
    48→            'etapa_movimiento_vacante_id'         => $request->etapa_movimiento_vacante_id,
    49→            'movimiento_vacante_configuracion_id' => $request->movimiento_vacante_configuracion_id
    50→        ];
    51→
    52→        $datos = ['valor' => $request->valor];
    53→
    54→        if ($request->filled('prueba_id')) {
    55→            $datos['prueba_id'] = $request->prueba_id;
    56→        }
    57→
    58→        if ($request->filled('perfil_id')) {
    59→            $datos['perfil_id'] = $request->perfil_id;
    60→        }
    61→
    62→        return $this->repositorio->crearOActualizar($condiciones, $datos);
    63→    }
    64→
    65→    /**
    66→     * Sincronizar varias configuraciones de movimientos de etapas.
    67→     *
    68→     * @param array $configuraciones Configuraciones de movimientos de etapas.
    69→     * @return void
    70→     * @author Daniel Beltrán
    71→     */
    72→    public function sincronizarVarios(array $configuraciones): void {
    73→        $configuraciones_mantener_ids = [];
    74→
    75→        foreach ($configuraciones as $configuracion) {
    76→            $configuracion_sincronizada = $this->sincronizar(new Request($configuracion));
    77→
    78→            if (!is_null($configuracion_sincronizada)) {
    79→                array_push($configuraciones_mantener_ids, $configuracion_sincronizada->id);
    80→            }
    81→        }
    82→
    83→        $etapa_movimiento = $this->etapa_movimiento_vacante_repositorio->getUno($configuraciones[0]['etapa_movimiento_vacante_id']);
    84→
    85→        if (is_null($etapa_movimiento)) {
    86→            return;
    87→        }
    88→
    89→        $this->repositorio->eliminarVariosAvanzado(new Request([
    90→            'etapa_movimiento_vacante_id' => $etapa_movimiento->id,
    91→            'mantener_ids'                => $configuraciones_mantener_ids
    92→        ]));
    93→
    94→        $this->actualizarProcesoRelacionado($etapa_movimiento);
    95→    }
    96→
    97→    /**
    98→     * Obtener la configuración del movimiento de pruebas psicométricas para la vacante especificada.
    99→     *
   100→     * @param Vacante $vacante Vacante.
   101→     * @return Collection
   102→     * @author Daniel Beltrán
   103→     */
   104→    public function obtenerConfiguracionPruebasPsicometricas(Vacante $vacante): Collection {
   105→        $etapa_pruebas_psicometricas            = $vacante->etapas->where('nombre', 'Pruebas psicométricas')->first();
   106→        $etapa_movimiento_pruebas_psicometricas = $this->etapa_movimiento_vacante_repositorio->getUnoAvanzado(new Request([
   107→            'etapa_vacante_id'      => $etapa_pruebas_psicometricas->id,
   108→            'movimiento_vacante_id' => MovimientoVacante::PRUEBAS_PSICOMETRICAS_ID
   109→        ]));
   110→
   111→        return $this->repositorio->getTodo(new Request(['etapa_movimiento_vacante_id' => $etapa_movimiento_pruebas_psicometricas->id]));
   112→    }
   113→
   114→    /**
   115→     * Actualizar el proceso asociado a la vacante cuando se modifican las configuraciones
   116→     * de la etapa de pruebas psicométricas.
   117→     *
   118→     * @param EtapaMovimientoVacante $etapa_movimiento Movimiento de la etapa actualizado.
   119→     * @return void
   120→     * @author Sergio Vargas
   121→     */
   122→    private function actualizarProcesoRelacionado(EtapaMovimientoVacante $etapa_movimiento): void {
   123→        if ($etapa_movimiento->movimiento_vacante_id !== MovimientoVacante::PRUEBAS_PSICOMETRICAS_ID) {
   124→            return;
   125→        }
   126→
   127→        $etapa_movimiento->loadMissing('etapa.vacante');
   128→
   129→        $vacante = $etapa_movimiento->etapa?->vacante;
   130→        if (is_null($vacante)) {
   131→            return;
   132→        }
   133→
   134→        $proceso = $this->proceso_repositorio->getUnoAvanzado(new Request(['vacante_id' => $vacante->id]));
   135→        if (is_null($proceso)) {
   136→            return;
   137→        }
   138→
   139→        $configuraciones_vigentes = $this->repositorio->getTodo(new Request(['etapa_movimiento_vacante_id' => $etapa_movimiento->id]));
   140→
   141→        $configuracion_dias = $configuraciones_vigentes->first(function ($configuracion) {
   142→            return $configuracion->movimientoConfiguracion?->llave === 'caducar_acceso_despues_de_dias_pruebas_psicometricas';
   143→        });
   144→
   145→        $configuracion_fecha = $configuraciones_vigentes->first(function ($configuracion) {
   146→            return $configuracion->movimientoConfiguracion?->llave === 'caducar_acceso_despues_de_fecha_pruebas_psicometricas';
   147→        });
   148→
   149→        $datos_actualizacion = [
   150→            'dias_vencimiento_agendas'  => null,
   151→            'fecha_vencimiento_agendas' => null,
   152→        ];
   153→
   154→        if (!is_null($configuracion_dias) && $configuracion_dias->valor !== null && $configuracion_dias->valor !== '') {
   155→            $datos_actualizacion['dias_vencimiento_agendas'] = $configuracion_dias->valor;
   156→        } elseif (!is_null($configuracion_fecha) && $configuracion_fecha->valor !== null && $configuracion_fecha->valor !== '') {
   157→            $datos_actualizacion['fecha_vencimiento_agendas'] = $configuracion_fecha->valor;
   158→        }
   159→
   160→        $this->proceso_repositorio->actualizar($proceso->id, $datos_actualizacion);
   161→    }
   162→}
