    15→
    16→/**
    17→ * @property PlantillaCorreoRepository $repositorio
    18→ */
    19→class PlantillaCorreoService extends BaseService
    20→{
    21→    /**
    22→     * Constructor.
    23→     *
    24→     * @param PlantillaCorreoRepository $repositorio Repositorio de plantillas de correo.
    25→     * @param VariableRepository $variable_repositorio Repositorio de variables.
    26→     * @param EmpresaUsuarioRepository $empresa_usuario_repositorio Repositorio de empresas usuarios.
    27→     * @return void
    28→     * @author Daniel Beltrán
    29→     * @author Fahibram Cárcamo
    30→     */
    31→    public function __construct(
    32→        PlantillaCorreoRepository $repositorio,
    33→        protected VariableRepository $variable_repositorio,
    34→        protected EmpresaUsuarioRepository $empresa_usuario_repositorio
    35→    ) {
    36→        parent::__construct($repositorio);
    37→    }
    38→
    39→    /**
    40→     * Guardar plantilla de correo.
    41→     *
    42→     * @param Request $request Contenido de la petición.
    43→     * @return PlantillaCorreo
    44→     * @author Daniel Beltrán
    45→     * @author Fahibram Cárcamo
    46→     */
    47→    public function guardar(Request $request): PlantillaCorreo {
    48→        $campos_excluidos = ['_token', '_method', 'id', 'nombre', 'descripcion', 'descripcion_mensaje'];
    49→
    50→        if ($request->filled('id')) {
    51→            // Identificar si se trata de una plantilla personalizada
