class ArchivoService extends BaseService {
    use ArchivoTrait;

    public function __construct(ArchivoRepository $repositorio) {
        parent::__construct($repositorio);
    }

    public function guardarVarios(string $modelo, int $id, array $archivos, string $carpeta, bool $conservar_nombre_original = false, ?bool $incluir_id_en_carpeta = true): void {
        $ruta = "private/archivos/{$carpeta}";

        if ($incluir_id_en_carpeta) {
            $ruta .= "/{$id}";
        }

        $this->generarDirectorios("app/{$ruta}");

        foreach ($archivos as $llave => $archivo) {
            $nombre_original = str_replace('_', '-', $llave) . date('YmdHis') . '.' . $archivo->getClientOriginalExtension();
            $nombre_archivo  = $this->generarNombreArchivo($archivo);
            $this->guardarArchivoEnRuta($archivo, $ruta, $nombre_archivo);

            $this->repositorio->crear([
                'modelo'                  => $modelo,
                'modelo_id'               => $id,
                'nombre'                  => $llave,
                'nombre_original_archivo' => $conservar_nombre_original ? $archivo->getClientOriginalName() : null,
                'ruta'                    => $ruta . '/' . $nombre_archivo
            ]);
        }
    }

    public function eliminarPorModelo(string $modelo, int $id, ?string $nombre = null): void {
        $archivos = $this->repositorio->getTodo(new Request([
            'modelo'    => $modelo,
            'modelo_id' => $id,
            'nombre'    => $nombre
        ]));

        if (!is_null($archivos)) {
            foreach ($archivos as $archivo) {
                $this->eliminarArchivoDesdeRuta($archivo->ruta);
                $this->repositorio->eliminar($archivo->id);
            }
        }
    }
