### 5.3 PlantillaCorreoService (`app/Http/Services/Configuraciones/PlantillaCorreoService.php`)

**Patrón avanzado - Lógica compleja de negocio**

```php
class PlantillaCorreoService extends BaseService {
    public function __construct(
        PlantillaCorreoRepository $repositorio,
        protected VariableRepository $variable_repositorio,
        protected EmpresaUsuarioRepository $empresa_usuario_repositorio
    ) {
        parent::__construct($repositorio);
    }

    public function guardar(Request $request): PlantillaCorreo {
        $campos_excluidos = ['_token', '_method', 'id', 'nombre', 'descripcion', 'descripcion_mensaje'];

        if ($request->filled('id')) {
            // Lógica para identificar si es plantilla personalizada
            if ($request->filled('empresa_id') && $request->filled('plantilla_correo_id')) {
                $plantilla = $this->obtenerUno($request);

                if (!is_null($plantilla) && !is_null($plantilla->empresa_id) && !is_null($plantilla->plantilla_correo_id)) {
                    $plantilla = $this->repositorio->actualizar($plantilla->id, $request->except($campos_excluidos));
                } else {
                    // Crear plantilla personalizada basada en la plantilla por defecto
                    $plantilla_por_defecto = $this->repositorio->getUno($request->plantilla_correo_id);
                    $plantilla = $this->repositorio->crear([
                        'plantilla_correo_id'   => $request->plantilla_correo_id,
                        'empresa_id'            => $request->empresa_id,
                        'grupo_id'              => $plantilla_por_defecto->grupo_id,
                        'nombre'                => $plantilla_por_defecto->nombre,
                        'descripcion'           => $plantilla_por_defecto->descripcion,
                        'asunto'                => $request->asunto ?? $plantilla_por_defecto->asunto,
                        'titulo'                => $request->titulo ?? $plantilla_por_defecto->titulo,
                        'contenido'             => $request->contenido ?? $plantilla_por_defecto->contenido,
                        'texto_boton'           => $request->texto_boton ?? $plantilla_por_defecto->texto_boton,
                        'enlace_boton'          => $request->enlace_boton ?? $plantilla_por_defecto->enlace_boton,
                        'con_logo_empresa'      => $request->con_logo_empresa ?? $plantilla_por_defecto->con_logo_empresa,
                        'notificar_fin_proceso' => $request->notificar_fin_proceso ?? $plantilla_por_defecto->notificar_fin_proceso
                    ]);
                }
            } else {
                $campos_excluidos = array_merge($campos_excluidos, ['empresa_id', 'plantilla_correo_id']);
                $plantilla = $this->repositorio->actualizar($request->id, $request->except($campos_excluidos));
            }
        } else {
            if ($request->filled('empresa_id') && $request->filled('plantilla_correo_id')) {
                $plantilla = $this->obtenerUno($request);
                if (!is_null($plantilla)) {
                    throw new Exception('Ya existe una plantilla personalizada para la acción indicada en esta empresa', 400);
                }
            } else {
                $plantilla = $this->repositorio->crear($request->except($campos_excluidos));
            }
        }

        return $plantilla;
    }

    public function extraerVariables(string $contenido): array {
        $variables = [];
        preg_match_all('/__(.*?)__/', $contenido, $coincidencias);

        if (!empty($coincidencias[1])) {
            $variables = $coincidencias[1];
        }

        return $variables;
    }

    public function restablecerPorDefecto(int $id): void {
        $plantilla = $this->repositorio->getUno($id);

        if (!is_null($plantilla->empresa_id) && !is_null($plantilla->plantilla_correo_id)) {
            $plantilla_origen = $this->repositorio->getUno($plantilla->plantilla_correo_id);

            $this->repositorio->actualizar($plantilla->id, [
                'titulo'    => $plantilla_origen->titulo,
                'contenido' => $plantilla_origen->contenido
            ]);
        }
    }

    public function obtenerUno(Request $request): PlantillaCorreo {
        $plantilla = $this->repositorio->getUnoAvanzado($request);

        if (is_null($plantilla)) {
            $plantilla = $this->repositorio->getUno($request->plantilla_correo_id);
        }

        return $plantilla;
    }

    public function obtenerTodo(Request $request): Collection {
        $request->merge(['plantilla_correo_id' => null, 'empresa_id' => null]);
        $plantillas     = $this->repositorio->getTodo($request);
        $empresa_actual = $this->empresa_usuario_repositorio->obtenerEmpresaActualUsuario(Auth::id());

        return $plantillas->map(function ($item) use ($request, $empresa_actual) {
            if ($empresa_actual->id !== Empresa::PSICOALIANZA_ID) {
                $plantilla_personalizada = $this->repositorio->getUnoAvanzado(new Request([
                    'plantilla_correo_id' => $item->id,
                    'empresa_id'          => $request->empresa_id
                ]));

                if (!is_null($plantilla_personalizada)) {
                    return $plantilla_personalizada;
                }
            }

            return $item;
        });
    }
}
```

### 5.4 EtapaMovimientoVacanteConfiguracionService (`app/Http/Services/Vacantes/EtapaMovimientoVacanteConfiguracionService.php`)

**Patrón con sincronización y actualización de procesos relacionados**

```php
class EtapaMovimientoVacanteConfiguracionService extends BaseService {
    public function __construct(
        EtapaMovimientoVacanteConfiguracionRepository $repositorio,
        protected EtapaMovimientoVacanteRepository $etapa_movimiento_vacante_repositorio,
        protected ProcesoRepository $proceso_repositorio
    ) {
        parent::__construct($repositorio);
    }

    public function sincronizar(Request $request): EtapaMovimientoVacanteConfiguracion {
        $condiciones = [
            'etapa_movimiento_vacante_id'         => $request->etapa_movimiento_vacante_id,
            'movimiento_vacante_configuracion_id' => $request->movimiento_vacante_configuracion_id
        ];

        $datos = ['valor' => $request->valor];

        if ($request->filled('prueba_id')) {
            $datos['prueba_id'] = $request->prueba_id;
        }

        if ($request->filled('perfil_id')) {
            $datos['perfil_id'] = $request->perfil_id;
        }

        return $this->repositorio->crearOActualizar($condiciones, $datos);
    }

    public function sincronizarVarios(array $configuraciones): void {
        $configuraciones_mantener_ids = [];

        foreach ($configuraciones as $configuracion) {
            $configuracion_sincronizada = $this->sincronizar(new Request($configuracion));

            if (!is_null($configuracion_sincronizada)) {
                array_push($configuraciones_mantener_ids, $configuracion_sincronizada->id);
            }
        }

        $etapa_movimiento = $this->etapa_movimiento_vacante_repositorio->getUno($configuraciones[0]['etapa_movimiento_vacante_id']);

        if (is_null($etapa_movimiento)) {
            return;
        }

        $this->repositorio->eliminarVariosAvanzado(new Request([
            'etapa_movimiento_vacante_id' => $etapa_movimiento->id,
            'mantener_ids'                => $configuraciones_mantener_ids
        ]));

        $this->actualizarProcesoRelacionado($etapa_movimiento);
    }

    public function obtenerConfiguracionPruebasPsicometricas(Vacante $vacante): Collection {
        $etapa_pruebas_psicometricas = $vacante->etapas->where('nombre', 'Pruebas psicométricas')->first();
        $etapa_movimiento_pruebas_psicometricas = $this->etapa_movimiento_vacante_repositorio->getUnoAvanzado(new Request([
            'etapa_vacante_id'      => $etapa_pruebas_psicometricas->id,
            'movimiento_vacante_id' => MovimientoVacante::PRUEBAS_PSICOMETRICAS_ID
        ]));

        return $this->repositorio->getTodo(new Request(['etapa_movimiento_vacante_id' => $etapa_movimiento_pruebas_psicometricas->id]));
    }

    private function actualizarProcesoRelacionado(EtapaMovimientoVacante $etapa_movimiento): void {
        if ($etapa_movimiento->movimiento_vacante_id !== MovimientoVacante::PRUEBAS_PSICOMETRICAS_ID) {
            return;
        }

        $etapa_movimiento->loadMissing('etapa.vacante');
        $vacante = $etapa_movimiento->etapa?->vacante;

        if (is_null($vacante)) {
            return;
        }

        $proceso = $this->proceso_repositorio->getUnoAvanzado(new Request(['vacante_id' => $vacante->id]));
        if (is_null($proceso)) {
            return;
        }

        // ... lógica de actualización
    }
}
